60	export const useRoomTimeline = ({ room, roomId }: Props) => {
61	  const [events, setEvents] = useState<EventTimelineItem[]>([]);
62	  /** Track processed verification request IDs to avoid duplicates */
63	  // const processedVerificationRequestsRef = useRef<Set<string>>(new Set());
64	  const eventIdsRef = useRef<Set<string>>(new Set());
65	  const timelineItemsRef = useRef<Array<EventTimelineItem | null>>([]);
66	  const timelineRef = useRef<TimelineInterface | null>(null);
67	  const isPaginatingRef = useRef(false);
68	  const reachedStartRef = useRef(false);
