70	  const setPinnedEventIds = useSetAtom(TimelineAtoms.pinnedEventIds);
71	  const [isDirect, setIsDirect] = useState(false);
72	  /** FIFO queue of transactionIds for in-flight own messages, used to match the final echo Set diff */
73	  const pendingTransactionIdsQueue = useRef<string[]>([]);
74	  const rebuildTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined);
75	
76	  const toEventItem = (item: TimelineItemInterface): EventTimelineItem | null =>
77	    item.asEvent() ?? null;
78	
79	  const rebuildEventsFromTimelineItems = useCallback(() => {
80	    const seenIds = new Set<string>();
81	    const nextEvents: EventTimelineItem[] = [];
82	
83	    for (const item of timelineItemsRef.current) {
84	      if (!item) continue;
85	      const key = getItemUniqueKey(item);
86	      if (key) {
87	        if (seenIds.has(key)) continue;
88	        seenIds.add(key);
89	      }
90	      nextEvents.push(item);
91	    }
92	
93	    eventIdsRef.current = seenIds;
94	    setEvents(nextEvents);
95	  }, []);
