131	  //       });
132	
133	  //       // Only handle one at a time
134	  //       break;
135	  //     }
136	  //   },
137	  //   [],
138	  // );
139	
140	  const markAsRead = useCallback(async () => {
141	    if (!room) return;
142	    if (AppState.currentState !== "active") return;
143	
144	    try {
145	      await room.markAsRead(ReceiptType.Read);
146	    } catch (error) {
147	      console.error("Failed to mark room as read:", error);
148	    }
149	  }, [room]);
150	
151	  const loadMoreMessages = useCallback(async () => {
152	    if (!timelineRef.current || isPaginatingRef.current || reachedStartRef.current) return;
153	
154	    isPaginatingRef.current = true;
155	
156	    try {
157	      const hitStart = await timelineRef.current.paginateBackwards(TIMELINE_PAGE_SIZE);
158	      if (hitStart) {
159	        reachedStartRef.current = true;
160	      }
161	    } catch (error) {
162	      console.error("Failed to load more messages:", error);
163	    } finally {
164	      isPaginatingRef.current = false;
165	    }
166	  }, []);
167	
168	  useEffect(() => {
169	    if (!room) return;
170	    setPinnedEventIds([]);
171	    TimelineService.getPinnedEventIds(roomId)
172	      .then(setPinnedEventIds)
173	      .catch(console.error);
174	  }, [room, roomId, setPinnedEventIds]);
