188	    const initRoomTimeline = async () => {
189	      try {
190	        const timeline = await room.timelineWithConfiguration({
191	          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
192	          filter: new TimelineFilter.All(),
193	          internalIdPrefix: undefined,
194	          dateDividerMode: DateDividerMode.Daily,
195	          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
196	          reportUtds: false,
197	        });
198	
199	        // Store timeline in ref for reuse in pagination
200	        timelineRef.current = timeline;
201	
202	        // Set up listener BEFORE paginateBackwards so the SDK's initial
203	        // cached diffs (from SQLite) are received immediately — no network needed.
204	        // Set up timeline listener for real-time updates
205	        timelineListenerHandle = await timeline.addListener({
206	          onUpdate: (diffs) => {
207	            const beforeCount = timelineItemsRef.current.length;
208	            diffs.forEach((diff) => {
209	              const change = diff.tag;
210	              const timelineItems = timelineItemsRef.current;
211	              switch (change) {
212	                case TimelineDiff_Tags.Append: {
213	                  if (diff.inner.values.length > 0) {
214	                    timelineItems.push(...diff.inner.values.map(toEventItem));
215	                  }
216	                  break;
217	                }
218	                case TimelineDiff_Tags.Insert: {
219	                  const { index, value } = diff.inner;
220	                  timelineItems.splice(index, 0, toEventItem(value));
221	                  break;
222	                }
223	                case TimelineDiff_Tags.Set: {
224	                  const { index, value } = diff.inner;
225	                  const ev = toEventItem(value);
226	                  timelineItems[index] = ev;
227	
228	                  // transactionId -> eventId transition can arrive in an order where
229	                  // a stale local echo still exists elsewhere in the list.
230	                  if (
231	                    ev?.isOwn &&
232	                    !ev.localSendState &&
233	                    pendingTransactionIdsQueue.current.length > 0
234	                  ) {
235	                    const txId = pendingTransactionIdsQueue.current.shift();
236	                    if (txId) {
237	                      const txIndex = timelineItems.findIndex((item) => {
238	                        if (!item) return false;
239	                        return getItemUniqueKey(item) === txId;
240	                      });
241	                      if (txIndex !== -1) {
242	                        timelineItems[txIndex] = ev;
243	                      }
244	                    }
245	                  }
246	                  break;
247	                }
248	                case TimelineDiff_Tags.Remove: {
249	                  const { index: removeIndex } = diff.inner;
250	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
251	                    timelineItems.splice(removeIndex, 1);
252	                  }
253	                  break;
254	                }
255	                case TimelineDiff_Tags.PushFront: {
256	                  const { value } = diff.inner;
